import React from 'react';
import styles from './desktop.module.css';
import { chimneySmoke, switchingWindows, type TownWindow } from './townData';

/**
 * The town at dawn behind the home page hero, in six depth planes (sky, then plane 5, the farthest,
 * to plane 1, the rooftop the visitor looks from). The static drawing of each plane is an image
 * generated by scripts/home-town/generate.mjs; this component layers those images and draws over
 * them only what moves (windows switching on, smoke, the crane's load, gulls, clouds), so the motion
 * can be paused and follows the reduced-motion setting. Each plane carries `data-depth`, which the
 * pointer parallax reads. Purely decorative: hidden from assistive technology.
 */

/** Same drawing space as the generated planes: 1440 x 900 plus a 40 px margin for the parallax. */
const VIEWBOX = '-40 -40 1520 980';

const STARS: [number, number, number, number][] = [
  [430, 62, 1, 0.55], [612, 176, 0.9, 0.4], [884, 72, 1, 0.45], [250, 130, 0.8, 0.35],
  [720, 250, 0.8, 0.3], [540, 300, 0.7, 0.25], [160, 210, 0.8, 0.3],
];

/** Low clouds lit from below by the sunrise: cx, cy, rx, ry, opacity. */
const CLOUDS: [number, number, number, number, number][] = [
  [960, 590, 190, 7, 0.7], [1210, 562, 130, 5, 0.6], [860, 628, 230, 6, 0.55],
  [1340, 612, 120, 6, 0.6], [430, 652, 280, 6, 0.45], [1080, 650, 160, 5, 0.5],
];

/** The rooftop chimney's two pots, in plane 1. */
const ROOFTOP_SMOKE: [number, number, number][] = [[180, 796, 5], [199, 798, 4]];

const GULL_WING = 'M-9 1 Q-5 -4 0 0 Q5 -4 9 1';

/** Wall colour of the nearest houses, used for the window bars drawn over their switching panes. */
const NEAR_WALL = '#162948';

/** An SVG drawn over a plane image, in the same drawing space and with the same anchoring. */
const Overlay: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <svg viewBox={VIEWBOX} preserveAspectRatio="xMaxYMax slice" focusable="false">
    {children}
  </svg>
);

/** One plane: its generated image, then what moves in it. */
const Plane: React.FC<{ depth: number; src?: string; children?: React.ReactNode }> = ({ depth, src, children }) => (
  <div className={styles.plane} data-depth={depth}>
    {src && <img src={src} alt="" width={1520} height={980} decoding="async" />}
    {children && <Overlay>{children}</Overlay>}
  </div>
);

/** Panes that switch on one by one; the nearest ones get a warm glass, a curtain and a window bar. */
const SwitchingWindows: React.FC<{ list: TownWindow[]; kind: 'l4' | 'mid' | 'near' }> = ({ list, kind }) => (
  <>
    <g filter="url(#town-bloom)">
      {list.map((w) => (
        <rect
          key={`${w.x}-${w.y}`}
          className={styles.lit}
          style={{ animationDelay: `${w.delay}s` }}
          x={w.x}
          y={w.y}
          width={w.w}
          height={w.h}
          fill={kind === 'near' ? 'url(#town-warm)' : '#F3C47B'}
          fillOpacity={kind === 'l4' ? 0.55 : 1}
        />
      ))}
    </g>
    {kind === 'near' &&
      list.map((w) => (
        <g key={`bar-${w.x}-${w.y}`}>
          {w.curtain && (
            <rect className={styles.lit} style={{ animationDelay: `${w.delay}s` }} x={w.x} y={w.y} width={w.w * 0.38} height={w.h} fill="#B9773F" fillOpacity={0.45} />
          )}
          <path d={`M${w.x + w.w / 2} ${w.y} v${w.h}`} stroke={NEAR_WALL} strokeWidth={0.9} strokeOpacity={0.8} />
        </g>
      ))}
  </>
);

/** Smoke puffs rising from a chimney pot, staggered over one 7 s cycle. */
const Smoke: React.FC<{ x: number; y: number; puffs: number; light?: boolean }> = ({ x, y, puffs, light }) => (
  <>
    {Array.from({ length: puffs }, (_, i) => (
      <circle
        key={i}
        className={`${styles.puff} ${light ? styles.puffLight : ''}`}
        style={{ animationDelay: `${(-i * 7) / puffs}s` }}
        cx={x}
        cy={y}
        r={5}
      />
    ))}
  </>
);

export const TownScene: React.FC = () => (
  <div className={styles.town} aria-hidden="true">
    <Plane depth={2}>
      <defs>
        <linearGradient id="town-sky" x1="0" y1="0" x2="0" y2="900" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#04091A" />
          <stop offset=".28" stopColor="#0A1733" />
          <stop offset=".5" stopColor="#15305E" />
          <stop offset=".64" stopColor="#2A4A80" />
          <stop offset=".72" stopColor="#4D6A9E" />
          <stop offset=".78" stopColor="#8696C0" />
          <stop offset=".83" stopColor="#C9B6C2" />
          <stop offset=".88" stopColor="#F1C3A2" />
        </linearGradient>
        <radialGradient id="town-dawn" cx="1180" cy="800" r="640" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#FFC79C" stopOpacity=".55" />
          <stop offset=".5" stopColor="#E8B7B0" stopOpacity=".18" />
          <stop offset="1" stopColor="#E8B7B0" stopOpacity="0" />
        </radialGradient>
        <linearGradient id="town-cloud" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#5E77A8" />
          <stop offset=".6" stopColor="#C9A7AE" />
          <stop offset="1" stopColor="#F6C6A2" />
        </linearGradient>
        <radialGradient id="town-venus" r=".5">
          <stop offset="0" stopColor="#FFFFFF" />
          <stop offset=".25" stopColor="#FFFFFF" stopOpacity=".6" />
          <stop offset="1" stopColor="#FFFFFF" stopOpacity="0" />
        </radialGradient>
        <radialGradient id="town-warm" cx=".5" cy=".42" r=".75">
          <stop offset="0" stopColor="#FFE6B0" />
          <stop offset="1" stopColor="#E9A257" />
        </radialGradient>
        <filter id="town-bloom" x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="2.6" result="b" />
          <feMerge>
            <feMergeNode in="b" />
            <feMergeNode in="b" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
        <filter id="town-soft" x="-20%" y="-200%" width="140%" height="500%">
          <feGaussianBlur stdDeviation="4" />
        </filter>
        <filter id="town-smoke" x="-100%" y="-100%" width="300%" height="300%">
          <feGaussianBlur stdDeviation="5" />
        </filter>
      </defs>
      <rect className={styles.skyFill} x="-40" y="-40" width="1520" height="980" fill="url(#town-sky)" />
      <rect className={styles.dawn} x="-40" y="-40" width="1520" height="980" fill="url(#town-dawn)" />
      {STARS.map(([cx, cy, r, o]) => (
        <circle key={`${cx}-${cy}`} className={styles.star} cx={cx} cy={cy} r={r} fill="#fff" opacity={o} />
      ))}
      <circle cx="986" cy="132" r="9" fill="url(#town-venus)" />
      <circle cx="986" cy="132" r="1.6" fill="#fff" />
      <g className={styles.clouds} filter="url(#town-soft)">
        {CLOUDS.map(([cx, cy, rx, ry, o]) => (
          <ellipse key={`${cx}-${cy}`} cx={cx} cy={cy} rx={rx} ry={ry} fill="url(#town-cloud)" opacity={o} />
        ))}
      </g>
    </Plane>

    <Plane depth={4} src="/images/home/town/layer-5.svg">
      <g className={styles.gulls}>
        {[styles.gullOne, styles.gullTwo].map((gull) => (
          <g key={gull} className={`${styles.gull} ${gull}`}>
            <path className={styles.wing} d={GULL_WING} stroke="#101D38" strokeWidth={1.6} fill="none" strokeLinecap="round" />
          </g>
        ))}
      </g>
    </Plane>

    <Plane depth={6} src="/images/home/town/layer-4.svg">
      <SwitchingWindows list={switchingWindows.l4} kind="l4" />
    </Plane>

    <Plane depth={9} src="/images/home/town/layer-3.svg">
      <SwitchingWindows list={switchingWindows.mid} kind="mid" />
      {/* The crane's trolley carries a load of beams back and forth over the site. */}
      <g className={styles.trolley} fill="#24395F">
        <rect x="1224" y="516" width="14" height="5" />
        <path d="M1229 521 V600 M1233 521 V600" stroke="#24395F" strokeWidth={0.9} />
        <rect x="1227" y="600" width="8" height="7" rx="1" />
        <path d="M1231 607 L1214 620 M1231 607 L1248 620" stroke="#24395F" strokeWidth={0.9} />
        <rect x="1208" y="620" width="46" height="5" />
        <rect x="1208" y="625" width="46" height="4" fill="#30477A" />
        <path d="M1208 620 H1254" stroke="#C6D4EF" strokeOpacity={0.5} />
      </g>
      <g filter="url(#town-bloom)">
        <circle className={styles.beacon} cx="1394" cy="464" r="2.6" fill="#FF4B3E" />
        <circle className={`${styles.beacon} ${styles.beaconLate}`} cx="1171" cy="504" r="2.2" fill="#FF4B3E" />
      </g>
      <g filter="url(#town-smoke)">
        {chimneySmoke.map(([x, y], i) => (
          <Smoke key={`${x}-${y}`} x={x} y={y} puffs={5 - (i % 2)} />
        ))}
      </g>
    </Plane>

    <Plane depth={13} src="/images/home/town/layer-2.svg">
      <SwitchingWindows list={switchingWindows.near} kind="near" />
    </Plane>

    <Plane depth={18} src="/images/home/town/layer-1.svg">
      <g filter="url(#town-smoke)">
        {ROOFTOP_SMOKE.map(([x, y, puffs]) => (
          <Smoke key={x} x={x} y={y} puffs={puffs} light />
        ))}
      </g>
    </Plane>

    <div className={styles.vignette} />
    <div className={styles.grain} />
  </div>
);
